const ELEMENT_ENGINE = new Map(Object.entries(ELEMENTS_BY_ENGINE).flatMap(([engine,names])=>names.map(name=>[name,engine])));
export function engineForElement(name){const e=ELEMENT_ENGINE.get(name); if(!e) throw new Error(`Unknown Visualizer element: ${name}`); return e;}
export function hasElement(name){return ELEMENT_ENGINE.has(name);}
export const REGISTRY_COUNTS = Object.freeze({elements:ALL_ELEMENTS.length,engines:Object.keys(ELEMENTS_BY_ENGINE).length});
